<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/_endpoint.php';
$bootstrapPath=forge_staff_resolve_bootstrap_path(); if($bootstrapPath===null){forge_staff_send_fallback_response(500,['status'=>'error','error'=>['code'=>'server_error','message'=>'Inventory is currently unavailable.']]);exit;}
try{require_once $bootstrapPath; if(strtoupper((string)($_SERVER['REQUEST_METHOD']??''))!=='POST'){\Forge\Server\ApiResponse::send(405,\Forge\Server\ApiResponse::error('method_not_allowed','This endpoint accepts POST requests only.'),['Allow'=>'POST']);exit;}\Forge\Server\requireAuthenticatedStaffSession($_SERVER);if(!\Forge\Server\OrderPayload::isJsonContentType($_SERVER['CONTENT_TYPE']??null)){\Forge\Server\ApiResponse::send(415,\Forge\Server\ApiResponse::error('unsupported_media_type','The request must use Content-Type: application/json.'));exit;}$p=\Forge\Server\OrderPayload::decodeJsonObject(file_get_contents('php://input')?:'');$id=is_string($p['id']??null)?trim($p['id']):'';$location=\Forge\Server\buildInventoryLocationRepositoryFromEnvironment()->saveLocation($p,$id?:null);\Forge\Server\ApiResponse::send(200,\Forge\Server\ApiResponse::success(['location'=>$location]));}catch(\Forge\Server\ApiProblem $e){\Forge\Server\ApiResponse::send($e->getHttpStatus(),\Forge\Server\ApiResponse::error($e->getErrorCodeValue(),$e->getSafeMessage()),$e->getHeaders());}catch(\Forge\Server\InventoryNotFoundException $e){\Forge\Server\ApiResponse::send(404,\Forge\Server\ApiResponse::error('inventory_not_found',$e->getMessage()));}catch(\Forge\Server\InventoryValidationException $e){\Forge\Server\ApiResponse::send(422,\Forge\Server\ApiResponse::error('invalid_request',$e->getMessage()));}catch(\Throwable $e){forge_staff_log_unexpected_exception($e,$bootstrapPath,'inventory location');forge_staff_send_fallback_response(500,['status'=>'error','error'=>['code'=>'server_error','message'=>'Inventory is currently unavailable.']]);}
